const contacts = Array.isArray($json.results) ? $json.results : [];
if (!contacts.length) return [{ json: { answer: 'I could not find a matching customer in HubSpot.', customer: null, next_step: 'Ask the caller for another identifier such as email or phone number.' } }];
const contact = contacts[0];
const p = contact.properties || {};
const name = [p.firstname, p.lastname].filter(Boolean).join(' ') || p.email || 'Matched customer';
return [{ json: { answer: `${name} is in HubSpot${p.company ? ` at ${p.company}` : ''}. Lifecycle stage: ${p.lifecyclestage || 'unknown'}. Lead status: ${p.hs_lead_status || 'unknown'}.`, customer: { id: contact.id, name, email: p.email, phone: p.phone, company: p.company, lifecycleStage: p.lifecyclestage, leadStatus: p.hs_lead_status }, next_step: 'Use this context to personalize the conversation.' } }];
